import Foundation
final class RecordingBadge: NSObject {
    private(set) var ticks = 0
    private(set) var timer: Timer?
    func start() {
        precondition(Thread.isMainThread)
        stop()
        timer = Timer.scheduledTimer(
            timeInterval: 3600, target: self,
            selector: #selector(tick), userInfo: nil, repeats: true
        )
    }
    @objc private func tick() { ticks += 1 }
    func stop() {
        precondition(Thread.isMainThread)
        timer?.invalidate(); timer = nil
    }
}

Пока Timer валиден, он держит target. Явный stop разрывает удержание; deinit не является способом войти в stop при цикле.
